def two_sum(nums, target):
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                return [i, j]
    return []


def main():
    # 输入格式: 第一行 target, 第二行 nums(空格分隔)
    target = int(input())
    nums = list(map(int, input().split()))
    print(two_sum(nums, target))


if __name__ == "__main__":
    main()

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []


def main():
    target = int(input())
    nums = list(map(int, input().split()))
    print(two_sum(nums, target))


if __name__ == "__main__":
    main()

from typing import List


def two_sum_all(nums: List[int], target: int) -> List[List[int]]:
    """返回所有不重复的下标对（含重复元素也能正确处理）。"""
    seen = {}
    res = []
    for i, x in enumerate(nums):
        if target - x in seen:
            # 同一个值可能对应多个下标
            for j in seen[target - x]:
                res.append([j, i])
        seen.setdefault(x, []).append(i)
    return res


def main():
    target = int(input())
    nums = list(map(int, input().split()))
    pairs = two_sum_all(nums, target)
    print(pairs[0] if pairs else [])


if __name__ == "__main__":
    main()
